files.customize/cmux-app.json:
{
  "$schema": "https://cmux.dev/schemas/cmux-app/2.json",
  "manifestVersion": 2,
  "id": "local/customize",
  "name": {
    "en": "Thread composer"
  },
  "version": "1.0.0",
  "description": "Attachments and microphone beside the draft.",
  "engines": {
    "cmux": "^2.0"
  },
  "implements": {
    "cmux.composer.toolbar/1": {
      "options": {
        "buttons": [
          {
            "action": "composer.attachFiles",
            "label": "Attach files"
          }
        ]
      }
    }
  }
}
